// components/public/restock-alert-modal.tsx — Priority Automated Restock Ping Form
// Direct integration with /api/public/restock-alert with stateful validation and confirmation.

"use client";

import React, { useState, useEffect } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { Bell, X, CheckCircle2, AlertCircle, RefreshCw, Send, ShieldCheck } from "lucide-react";

export interface RestockAlertModalProps {
  isOpen: boolean;
  onClose: () => void;
  productName: string;
  variantName?: string;
  slotCode?: string;
}

export function RestockAlertModal({
  isOpen,
  onClose,
  productName,
  variantName,
  slotCode,
}: RestockAlertModalProps) {
  const [contactHandle, setContactHandle] = useState("");
  const [notes, setNotes] = useState("");
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [submitted, setSubmitted] = useState(false);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!contactHandle.trim()) {
      setError("Please provide an email or Telegram handle.");
      return;
    }

    setLoading(true);
    setError(null);

    try {
      const res = await fetch("/api/public/restock-alert", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          contactHandle: contactHandle.trim(),
          productName,
          variantName,
          slotCode,
          notes: notes.trim(),
        }),
      });

      const data = await res.json();
      if (!res.ok || !data.success) {
        throw new Error(data.message || "Unable to register restock alert right now.");
      }

      setSubmitted(true);
    } catch (err: any) {
      setError(err?.message || "Failed to subscribe to restock alert. Please try again.");
    } finally {
      setLoading(false);
    }
  };

  const handleModalClose = () => {
    setSubmitted(false);
    setError(null);
    setContactHandle("");
    setNotes("");
    onClose();
  };

  useEffect(() => {
    if (!isOpen) return;
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === "Escape") {
        handleModalClose();
      }
    };
    window.addEventListener("keydown", handleKeyDown);
    return () => window.removeEventListener("keydown", handleKeyDown);
  }, [isOpen]);

  return (
    <AnimatePresence>
      {isOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
          {/* Backdrop */}
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            onClick={handleModalClose}
            className="fixed inset-0 bg-black/80 backdrop-blur-md"
          />

          {/* Spring-Animated Dialog Card */}
          <motion.div
            initial={{ opacity: 0, scale: 0.95, y: 12 }}
            animate={{ opacity: 1, scale: 1, y: 0 }}
            exit={{ opacity: 0, scale: 0.95, y: 12 }}
            transition={{ type: "spring", damping: 30, stiffness: 350, mass: 0.8 }}
            className="relative w-full max-w-md rounded-2xl bg-white dark:bg-[#0D0E12] border border-neutral-200/80 dark:border-white/10 shadow-2xl p-6 z-10 overflow-hidden text-neutral-900 dark:text-zinc-100 font-sans"
          >
            {/* Close Button */}
            <button
              type="button"
              onClick={handleModalClose}
              className="absolute top-4 right-4 p-1.5 rounded-xl border border-neutral-200 dark:border-white/10 bg-neutral-100 dark:bg-white/5 text-neutral-500 hover:text-neutral-900 dark:text-zinc-400 dark:hover:text-white hover:bg-neutral-200 dark:hover:bg-white/10 transition-colors cursor-pointer"
            >
              <X className="w-4 h-4" />
            </button>

            {submitted ? (
              <div className="py-6 text-center space-y-4">
                <div className="w-12 h-12 rounded-2xl bg-neutral-100 dark:bg-white/10 border border-neutral-200 dark:border-white/20 text-neutral-900 dark:text-white flex items-center justify-center mx-auto shadow-inner">
                  <CheckCircle2 className="w-6 h-6" />
                </div>
                <div className="space-y-1">
                  <h3 className="text-lg font-bold font-sans text-neutral-900 dark:text-white">
                    Restock Alert Configured
                  </h3>
                  <p className="text-xs text-neutral-600 dark:text-zinc-400 max-w-xs mx-auto leading-relaxed">
                    We will notify <span className="font-mono text-neutral-900 dark:text-white font-medium">{contactHandle}</span> the second new inventory for <span className="text-neutral-900 dark:text-white font-medium">{productName}</span> is decrypted into the active vault.
                  </p>
                </div>
                <button
                  type="button"
                  onClick={handleModalClose}
                  className="w-full py-2.5 px-4 rounded-xl bg-neutral-900 hover:bg-neutral-800 text-white dark:bg-white dark:hover:bg-neutral-200 dark:text-neutral-950 font-sans font-semibold text-xs tracking-wide active:scale-[0.98] transition-all cursor-pointer mt-2"
                >
                  Done
                </button>
              </div>
            ) : (
              <div className="space-y-5">
                <div className="space-y-1.5 text-left">
                  <div className="text-[10px] font-mono font-medium tracking-[0.2em] text-neutral-500 dark:text-neutral-400 uppercase">
                    <span>INSTANT SOURCING PING</span>
                  </div>
                  <h3 className="text-lg font-bold font-sans text-neutral-900 dark:text-white tracking-tight">
                    Restock Alert Notification
                  </h3>
                  <p className="text-xs text-neutral-600 dark:text-zinc-400 leading-relaxed">
                    <strong className="text-neutral-900 dark:text-zinc-200 font-medium">{productName}</strong>
                    {variantName ? ` (${variantName})` : ""} is currently depleted. Register your handle for priority dispensing upon inventory deposit.
                  </p>
                </div>

                {error && (
                  <div className="p-3 rounded-xl border border-rose-500/20 bg-rose-500/10 text-rose-600 dark:text-rose-300 text-xs font-mono flex items-center space-x-2">
                    <AlertCircle className="w-4 h-4 shrink-0 text-rose-500 dark:text-rose-400" />
                    <span>{error}</span>
                  </div>
                )}

                <form onSubmit={handleSubmit} className="space-y-3.5">
                  <div>
                    <label className="block text-[11px] font-mono uppercase tracking-wider text-neutral-600 dark:text-zinc-400 mb-1.5">
                      Email or Telegram Handle *
                    </label>
                    <div className="relative">
                      <input
                        type="text"
                        required
                        value={contactHandle}
                        onChange={(e) => setContactHandle(e.target.value)}
                        placeholder="buyer@domain.com or @telegram_user"
                        className="w-full px-3.5 py-2.5 rounded-xl border border-neutral-300 dark:border-white/10 bg-neutral-50 dark:bg-white/5 text-xs font-mono text-neutral-900 dark:text-white placeholder:text-neutral-400 dark:placeholder:text-zinc-500 focus:outline-none focus:border-neutral-500 dark:focus:border-white/40 focus:ring-1 focus:ring-neutral-400 dark:focus:ring-white/20 transition-all"
                      />
                    </div>
                  </div>

                  <div>
                    <label className="block text-[11px] font-mono uppercase tracking-wider text-neutral-600 dark:text-zinc-400 mb-1.5">
                      Target Quantity / Plan Details (Optional)
                    </label>
                    <input
                      type="text"
                      value={notes}
                      onChange={(e) => setNotes(e.target.value)}
                      placeholder="e.g. 5x bulk slots needed for team"
                      className="w-full px-3.5 py-2.5 rounded-xl border border-neutral-300 dark:border-white/10 bg-neutral-50 dark:bg-white/5 text-xs font-mono text-neutral-900 dark:text-white placeholder:text-neutral-400 dark:placeholder:text-zinc-500 focus:outline-none focus:border-neutral-500 dark:focus:border-white/40 focus:ring-1 focus:ring-neutral-400 dark:focus:ring-white/20 transition-all"
                    />
                  </div>

                  <div className="pt-2">
                    <button
                      type="submit"
                      disabled={loading || !contactHandle.trim()}
                      className="w-full min-h-[44px] py-2.5 px-4 rounded-xl bg-neutral-900 hover:bg-neutral-800 text-white dark:bg-white dark:hover:bg-neutral-200 dark:text-neutral-950 font-sans font-semibold text-xs tracking-wide active:scale-[0.98] disabled:opacity-50 transition-all duration-100 ease-out flex items-center justify-center space-x-2 cursor-pointer"
                    >
                      {loading ? (
                        <>
                          <RefreshCw className="w-4 h-4 animate-spin" />
                          <span>Configuring Alert...</span>
                        </>
                      ) : (
                        <>
                          <Send className="w-3.5 h-3.5" />
                          <span>Notify Me on Restock</span>
                        </>
                      )}
                    </button>
                  </div>
                </form>

                <div className="flex items-center justify-center space-x-1.5 text-[10px] font-mono text-neutral-500 dark:text-zinc-500 pt-1 border-t border-neutral-200 dark:border-white/10">
                  <ShieldCheck className="w-3 h-3 text-neutral-500 dark:text-neutral-400" />
                  <span>Zero spam. Pinged only upon vault replenishment.</span>
                </div>
              </div>
            )}
          </motion.div>
        </div>
      )}
    </AnimatePresence>
  );
}
export default RestockAlertModal;
